{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "ReactNode",
      "description": "Primary label text for the item.",
      "required": true
    },
    {
      "name": "icon",
      "type": "IconType",
      "description": "Icon displayed before the label. See `astryx docs icons` for valid semantic names."
    },
    {
      "name": "description",
      "type": "ReactNode",
      "description": "Secondary description text displayed below the label."
    },
    {
      "name": "layout",
      "type": "'stacked' | 'inline'",
      "description": "How the label and description sit together. 'stacked' puts the description on its own line; 'inline' keeps both on one line so the row fits a fixed-height host. Inside a Selector trigger the trigger's padding sizes itself to whichever layout you pick, so both land on the 4px rhythm; an InputGroup pins the row height and forces 'inline'.",
      "default": "'stacked'"
    },
    {
      "name": "endContent",
      "type": "ReactNode",
      "description": "Additional content rendered after the label and description."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
